import{acquirePrologueEnvironment}from'./environment-loader.mjs';
import{loadLowerShrubLayer}from'./lower-shrub-layer.mjs';
import{JUNCTION}from'./junction-registration.mjs';
import{createJunctionOverlay}from'./junction-overlay.mjs';
import{createOpeningOverlay}from'./opening-overlay-feather.mjs';
const moduleURL=import.meta.url;
export const PROLOGUE_VISUAL_REVISION=Object.freeze({revision:'PROLOGUE_FOREST_OPENINGS_IMAGEGEN_CLIPPED_OVERLAY_R5',patchSHA:'c6bdc6b656086e99e6c436514083b1e133dc97dc1d48e0c7f372c1ae7ce29e00',width:2035,height:773});
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadPrologueVisualLayer({fetcher=fetch,decode=async b=>createImageBitmap(new Blob([b])),signal,canvasFactory=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c}}={}){let environment=null,image=null,layer=null,junctionImage=null,junction=null,lower=null,disposed=false;const check=()=>{if(signal?.aborted)throw Error('PROLOGUE_VISUAL_CANCELLED')};const dispose=()=>{if(disposed)return;disposed=true;environment?.dispose();layer?.dispose();junction?.dispose();lower?.dispose();image?.close?.();junctionImage?.close?.()};try{check();const r=await fetcher(new URL('./assets/forest-openings-r5.png',moduleURL),{signal});if(!r.ok)throw Error('PROLOGUE_VISUAL_MISSING');const raw=await r.arrayBuffer(),bytes=raw instanceof ArrayBuffer?new Uint8Array(raw.slice(0)):new Uint8Array(raw);check();if(await hash(bytes)!==PROLOGUE_VISUAL_REVISION.patchSHA)throw Error('PROLOGUE_VISUAL_PIN_MISMATCH');check();image=await decode(bytes);check();if(image.width!==2035||image.height!==773)throw Error('PROLOGUE_VISUAL_DIMENSIONS');layer=createOpeningOverlay({patch:image,canvasFactory});const jr=await fetcher(new URL('./assets/junction-lamp-r3.png',moduleURL),{signal});if(!jr.ok)throw Error('JUNCTION_VISUAL_MISSING');const jraw=await jr.arrayBuffer(),jb=jraw instanceof ArrayBuffer?new Uint8Array(jraw.slice(0)):new Uint8Array(jraw);check();if(await hash(jb)!==JUNCTION.patchSHA)throw Error('JUNCTION_VISUAL_PIN_MISMATCH');check();junctionImage=await decode(jb);check();junction=createJunctionOverlay({patch:junctionImage,canvasFactory});lower=await loadLowerShrubLayer({fetcher,decode,signal,canvasFactory});check();environment=await acquirePrologueEnvironment({fetcher,signal});check();return Object.freeze({revision:PROLOGUE_VISUAL_REVISION,draw(ctx,options){if(!disposed){layer.draw(ctx,options);junction.draw(ctx,options);lower.draw(ctx,options);environment.drawBackground(ctx,{origin:[options.offsetX,options.offsetY],timeMs:options.elapsedMs??0})}},drawForeground(ctx,options){if(!disposed)junction.drawForeground(ctx,options)},junctionRegistration:JUNCTION,dispose});}catch(e){dispose();throw e}}
